                "title": "Ciarbharr",
                "subtitle": "Die Dämmerernte · Rotbier",
                "image": "./public/assets/gortach-brauerei/bier-ciarbharr.png",
                "imageFormat": "portrait",
                "imageFit": "contain",
                "imagePosition": "center",
